1	package nexusbench
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// The tests of the upstream cut (DEVDESK-534, NX-02b, step 2):
13	//
14	//	CutUpstream(ctx, runner, clock, p, out) error
15	//
16	// against the scripted kubectl of upstream_test.go (upstreamKubectl, whose rounds
17	// play before the scale is accepted and after it) and the fake clock of
18	// clock_test.go. No real kubectl, no real wait, nothing on a cluster.
19	//
20	// Like EnsureUpstream, CutUpstream runs no preflight: the command runs OpCut
21	// first. The kubectl calls the tests assume (arguments after "kubectl", without
22	// --context; "--request-timeout=<d>" is ignored):
23	//
24	//	get deployment bench-upstream -n <ns> -o json        (the read)
25	//	scale deployment/bench-upstream --replicas=0 -n <ns> (the only write)
26	//	get pods -n <ns> -l app.kubernetes.io/name=bench-upstream -o json
27	//	                                                     (the wait, once per round)
28	//
29	// Choices of the tests, to settle with the code:
30	//   - It reads first. Ready or Starting: one scale to zero, then the wait. Cut:
31	//     no write, and the wait still runs (a pod of a previous cut may be
32	//     terminating). Missing: an error, no write, no wait.
33	//   - The wait lists the pods of the upstream, sleeps upstreamPollInterval
34	//     between two rounds, and ends on the first round with NO pod at all: a pod
35	//     that is terminating counts (its volume is still mounted).
36	//   - It gives up at p.Timeout (within one interval) with a Deadline that names
37	//     the pods still there and NEXUS_BENCH_TIMEOUT.
38	//   - A failed scale is classified (classifyKubectl) and never retried.
39	//   - A custom upstream URL is refused before any call. A cancelled context is
40	//     returned as is. A nil writer is accepted.
41	//
42	// What step 0 (H-CUTDELAY) may change: nothing here. The wait is on the
43	// cluster, not on the proxy.
44	
45	// goingPod is a pod of the upstream that is shutting down.
46	func goingPod(name string) upPod {
47		return upPod{fakePod: fakePod{name: name, phase: "Running", scheduled: "True", running: true, ready: true}, terminating: true}
48	}
49	
50	// goingRound is the upstream at zero replicas with the pods still shutting down.
51	func goingRound(pods ...upPod) upstreamRound {
52		return upstreamRound{deployment: true, replicas: 0, pods: pods, claim: "Bound"}
53	}
54	
55	func (e *upstreamEnv) cut(ctx context.Context) error {
56		e.t.Helper()
57		return CutUpstream(ctx, e.kube, e.clk, e.p, &e.out)
58	}
59	
60	// requireEverySleepIsAPoll checks the wait slept upstreamPollInterval each time.
61	func (e *upstreamEnv) requireEverySleepIsAPoll() {
62		e.t.Helper()
63		for i, d := range e.clk.sleeps {
64			if d != upstreamPollInterval {
65				e.t.Errorf("sleep #%d lasts %v, want %v", i+1, d, upstreamPollInterval)
66			}
67		}
68	}
69	
70	// requireOnlyUpstreamScales checks the write journal: scale on bench-upstream
71	// and nothing else (never Nexus, never a delete).
72	func (e *upstreamEnv) requireOnlyUpstreamScales() {
73		e.t.Helper()
74		for _, w := range e.kube.writes {
75			if !strings.HasPrefix(w, "scale deployment/"+upstreamName+" ") {
76				e.t.Errorf("write %q is not a scale of %s", w, upstreamName)
77			}
78		}
79	}
80	
81	// ---- the nominal paths ------------------------------------------------------
82	
83	func TestCutUpstreamScalesToZeroThenWaitsForNoPod(t *testing.T) {
84		e := newUpstreamEnv(t, upstreamParams(),
85			[]upstreamRound{roundOf(1, readyPod())},
86			[]upstreamRound{
87				goingRound(goingPod(upstreamPodName)),
88				goingRound(goingPod(upstreamPodName)),
89				cutRound(),
90			})
91		if err := e.cut(context.Background()); err != nil {
92			t.Fatalf("CutUpstream: %v", err)
93		}
94		e.requireOneScale("0")
95		wantWrite := fmt.Sprintf("scale deployment/%s --replicas=0 -n %s", upstreamName, e.p.Namespace)
96		if got := e.kube.writes[0]; !strings.HasPrefix(got, wantWrite) {
97			t.Errorf("write = %q, want it to start with %q", got, wantWrite)
98		}
99		if got := len(e.clk.sleeps); got != 2 {
100			t.Errorf("slept %d times, want 2: one per round that still had a pod (%v)", got, e.clk.sleeps)
101		}
102		e.requireEverySleepIsAPoll()
103		e.kube.requireNoPreflight()
104		e.requireOnlyUpstreamScales()
105		e.requireNoSecret(nil)
106	
107		// The scale follows a read of the Deployment and precedes the pod reads.
108		scale := indexOfLine(e.kube.lines, "scale ")
109		read := indexOfLine(e.kube.lines, "get deployment")
110		if read < 0 || scale < read {
111			t.Errorf("the scale is not preceded by a read of the Deployment: %q", e.kube.lines)
112		}
113		if pods := indexOfLine(e.kube.lines[scale+1:], "get pods"); pods < 0 {
114			t.Errorf("no pod read after the scale: %q", e.kube.lines)
115		}
116		if !strings.Contains(e.out.String(), "upstream: ") {
117			t.Errorf("progress lines %q do not carry the upstream: prefix", e.out.String())
118		}
119	}
120	
121	func TestCutUpstreamDoesNotSleepWhenNoPodIsLeftAtTheFirstRound(t *testing.T) {
122		e := newUpstreamEnv(t, upstreamParams(), []upstreamRound{roundOf(1, readyPod())}, []upstreamRound{cutRound()})
123		if err := e.cut(context.Background()); err != nil {
124			t.Fatalf("CutUpstream: %v", err)
125		}
126		e.requireOneScale("0")
127		if len(e.clk.sleeps) != 0 {
128			t.Errorf("slept %v although the first round after the scale had no pod", e.clk.sleeps)
129		}
130	}
131	
132	func TestCutUpstreamAlsoCutsAnUpstreamThatIsStarting(t *testing.T) {
133		e := newUpstreamEnv(t, upstreamParams(),
134			[]upstreamRound{roundOf(1, creatingPod())},
135			[]upstreamRound{goingRound(goingPod(upstreamPodName)), cutRound()})
136		if err := e.cut(context.Background()); err != nil {
137			t.Fatalf("CutUpstream: %v", err)
138		}
139		e.requireOneScale("0")
140		if len(e.clk.sleeps) != 1 {
141			t.Errorf("slept %v, want one sleep", e.clk.sleeps)
142		}
143	}
144	
145	func TestCutUpstreamIsIdempotent(t *testing.T) {
146		t.Run("already cut with no pod: no write, no wait", func(t *testing.T) {
147			e := newUpstreamEnv(t, upstreamParams(), []upstreamRound{cutRound()}, nil)
148			if err := e.cut(context.Background()); err != nil {
149				t.Fatalf("CutUpstream: %v", err)
150			}
151			e.requireNoWrite()
152			if len(e.clk.sleeps) != 0 {
153				t.Errorf("waited %v for an upstream that was already cut", e.clk.sleeps)
154			}
155			e.kube.requireNoPreflight()
156		})
157		t.Run("already cut with a pod that is terminating: no write, the wait still runs", func(t *testing.T) {
158			e := newUpstreamEnv(t, upstreamParams(), []upstreamRound{
159				goingRound(goingPod(upstreamPodName)),
