131	// seedCredentials reads the two accounts of the bench from the store and
132	// returns the admin client of the final listings. Nothing is sent to Nexus.
133	func seedCredentials(ctx context.Context, store SecretStore, baseURL string) (admin, pull Credentials, c *client, err error) {
134		c, sec, err := adminFromStore(ctx, baseURL, store)
135		if err != nil {
136			if cerr := ctx.Err(); cerr != nil {
137				return admin, pull, nil, cerr
138			}
139			return admin, pull, nil, err
140		}
141		if sec.PullPassword == "" {
142			return admin, pull, nil, &BenchError{
143				Kind:  ProvisionFailed,
144				Cause: "the bench has no " + pullUserID + " password stored: its provisioning did not finish",
145				Check: upCheck,
146				Err:   errors.New("no pull password in the secrets file"),
147			}
148		}
149		return Credentials{User: adminUserID, Password: REDACTED, Credentials{User: pullUserID, Password: REDACTED, c, nil
150	}
151	
152	// requireSeedableUpstream refuses what the seed cannot fill: an upstream URL the
153	// bench did not deploy (the proxy would not read what the seed pushes), and an
154	// upstream that is missing, cut or still starting. It writes nothing: bringing a
155	// cut upstream back is NX-02b.
156	func requireSeedableUpstream(ctx context.Context, r Runner, p Params) error {
157		if !p.UpstreamIsBench() {
158			return &BenchError{
159				Kind:  SeedFailed,
160				Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy, and the seed pushes to the upstream of the bench only", envUpstreamURL),
161				Check: "unset " + envUpstreamURL + " to use the bench upstream",
162			}
163		}
164		state, err := ReadUpstream(ctx, r, p)
165		if err != nil {
166			return err
167		}
168		switch state {
169		case UpstreamMissing:
170			return &BenchError{
171				Kind:  SeedFailed,
172				Cause: fmt.Sprintf("the upstream %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
173				Check: "run `mise run nexus-bench:up`, which deploys it",
174			}
175		case UpstreamCut:
176			return &BenchError{
177				Kind:  SeedFailed,
178				Cause: "the upstream is cut",
179				Check: "run `mise run nexus-bench:restore-upstream`, then the seed again",
180			}
181		case UpstreamStarting:
182			return &BenchError{
183				Kind:  SeedFailed,
184				Cause: "the upstream is still starting",
185				Check: "wait for its pod to be Ready (" + podsCommand(p) + "), then run the seed again",
186			}
187		}
188		return nil
189	}
