210	// writeLayout writes the data set as an OCI layout under root.
211	func (s *seeder) writeLayout(root string) error {
212		s.layout = filepath.Join(root, "layout")
213		err := os.Mkdir(s.layout, 0o700)
214		if err == nil {
215			s.refs, err = WriteLayout(s.layout, s.images)
216		}
217		if err != nil {
218			return &BenchError{
219				Kind:  SeedFailed,
220				Cause: "the OCI layout of the data set cannot be written",
221				Check: "check that TMPDIR has room and is writable",
222				Err:   err,
223			}
224		}
225		return nil
226	}
