60	// requireEverySleepIsAPoll checks the wait slept upstreamPollInterval each time.
61	func (e *upstreamEnv) requireEverySleepIsAPoll() {
62		e.t.Helper()
63		for i, d := range e.clk.sleeps {
64			if d != upstreamPollInterval {
65				e.t.Errorf("sleep #%d lasts %v, want %v", i+1, d, upstreamPollInterval)
66			}
67		}
68	}
