70	// requireOnlyUpstreamScales checks the write journal: scale on bench-upstream
71	// and nothing else (never Nexus, never a delete).
72	func (e *upstreamEnv) requireOnlyUpstreamScales() {
73		e.t.Helper()
74		for _, w := range e.kube.writes {
75			if !strings.HasPrefix(w, "scale deployment/"+upstreamName+" ") {
76				e.t.Errorf("write %q is not a scale of %s", w, upstreamName)
77			}
78		}
79	}
