410	// indexOfLine is the index of the first recorded call that starts with prefix,
411	// -1 when there is none.
412	func indexOfLine(lines []string, prefix string) int {
413		for i, l := range lines {
414			if strings.HasPrefix(l, prefix) {
415				return i
416			}
417		}
418		return -1
