248	// seedUpstream pushes the upstream images through a port-forward that is always
249	// stopped before it returns.
250	func (s *seeder) seedUpstream() error {
251		local, stop, err := s.d.Forwarder.Forward(s.ctx, s.p.Namespace, upstreamServiceName, upstreamServicePort)
252		if err != nil {
253			return s.failure(err, "the port-forward to the upstream")
254		}
255		if stop != nil {
256			defer func() { _ = stop() }()
257		}
258		if !strings.HasPrefix(local, seedLoopbackHost+":") || !loopbackRegistry(local) {
259			return &BenchError{
260				Kind:  SeedFailed,
261				Cause: "the port-forward to the upstream is not on 127.0.0.1",
262				Check: "the bench pushes to a registry on the loopback only: check the kubectl on PATH",
263			}
264		}
265		for i, img := range s.images {
266			if img.Location != LocationUpstream {
267				continue
268			}
269			if err := s.push(i, upstreamImageRef(local, img), nil, "the upstream"); err != nil {
270				return err
271			}
272		}
273		return nil
274	}
