276	// seedHosted pushes the docker-hosted images with the admin account.
277	func (s *seeder) seedHosted() error {
278		for i, img := range s.images {
279			if img.Location != LocationHosted {
280				continue
281			}
282			if err := s.push(i, nexusImageRef(s.p, dockerHostedRepository, img), &s.admin, dockerHostedRepository); err != nil {
283				return err
284			}
285		}
286		return nil
287	}
