209	// parseGet reads "get <resource>[/<name>] [<name>] [flags]"; ok is false for a
210	// resource the fake does not script itself (it goes to the preflight fake).
211	func (u *upstreamKubectl) parseGet(norm []string) (getCall, bool) {
212		var g getCall
213		var positional []string
214		for i := 1; i < len(norm); i++ {
215			switch norm[i] {
216			case "-n", "--namespace":
217				i++
218				g.namespace = at(norm, i)
219			case "-l", "--selector":
220				i++
221				g.selector = at(norm, i)
222			case "-o", "--output":
223				i++
224				g.output = at(norm, i)
225			default:
226				if strings.HasPrefix(norm[i], "-") {
227					return g, false
228				}
229				positional = append(positional, norm[i])
230			}
231		}
232		if len(positional) == 0 {
233			return g, false
234		}
235		resource, name, _ := strings.Cut(positional[0], "/")
236		if g.kind = kindOfResource(resource); g.kind == "" {
237			return g, false
238		}
239		g.name = name
240		if len(positional) > 1 {
241			g.name = positional[1]
242		}
243		if len(positional) > 2 || (len(positional) == 2 && strings.Contains(positional[0], "/")) {
244			u.t.Errorf("unscripted arguments in %q", norm)
245		}
246		if g.namespace != u.p.Namespace {
247			u.t.Errorf("%q reads namespace %q, the run is about %q", norm, g.namespace, u.p.Namespace)
248		}
249		if g.output != "json" {
250			u.t.Errorf("%q must ask for -o json", norm)
251		}
252		return g, true
253	}
254	
255	func notFoundReply(what string) ([]byte, []byte, error) {
256		return nil, []byte("Error from server (NotFound): " + what + " not found\n"), errFakeExit1
257	}
