401	// requireNoPreflight checks the call set holds no question of the preflight.
402	func (u *upstreamKubectl) requireNoPreflight() {
403		u.t.Helper()
404		for _, line := range u.lines {
405			for _, banned := range []string{"auth ", "config ", "get namespace", "get nodes", "get services", "get --raw"} {
406				if strings.HasPrefix(line, banned) {
407					u.t.Errorf("call %q belongs to the preflight, which the caller runs", line)
408				}
409			}
410		}
411	}
