194	// seedCopier is the ImageCopier of the tests. It models the three registries the
195	// way the real ones behave: the upstream (reached only while the port-forward is
196	// open, no authentication), docker-hosted (admin) and docker-proxy (bench-pull, a
197	// read pulls the image through and caches it). Hosted and proxy contents are
198	// mirrored into the fake Nexus listing. It reads the layout Seed wrote, so a copy
199	// puts the digest of the image the layout says, and a wrong reference to the
200	// layout shows.
201	type seedCopier struct {
202		t     *testing.T
203		log   *orderLog
204		fwd   *fakeForwarder
205		nexus *fakeNexus
206		p     *Params
207		tmp   string
208	
209		admin, pull Credentials
210	
211		index map[string]refInfo // imageArg -> what it is
212	
213		upstream, hosted, proxyCache map[string]string // "name:tag" -> manifest digest
214		listing                      map[string][]fakeComponent
215		hidden                       map[string]bool // repositories whose listing is not published yet
216	
217		copies    []copyCall
218		digests   []digestCall
219		ociCopies int
220	
221		// absentText is the output of skopeo the fake reports for an absent image.
222		absentText string
223		// blind lists the repositories whose listing carries no digest (H-COMPONENTS:
224		// the instance may not list the manifest asset).
225		blind map[string]bool
226	
227		// copyErr, when set, runs at the start of the n-th Copy (1-based); a non-nil
228		// answer is the result of the Copy.
229		copyErr func(n int, c copyCall) error
230		// digestErr, when set, runs at the start of every ManifestDigest.
231		digestErr func(c digestCall) error
232	}
