254	func nameTag(img DatasetImage) string { return img.Name + ":" + img.Tag }
255	
256	func sameCreds(got, want *Credentials) bool {
257		if got == nil || want == nil {
258			return got == want
259		}
260		return got.User == want.User && got.Password == want.Password
261	}
262	
263	func (c *seedCopier) lookup(ref ImageRef) (refInfo, bool) {
264		if c.index == nil {
265			c.index = map[string]refInfo{}
266			for _, img := range Dataset() {
267				switch img.Location {
268				case LocationHosted:
269					c.index[imageArg(nexusImageRef(*c.p, dockerHostedRepository, img))] = refInfo{whereHosted, img}
270				case LocationUpstream:
271					c.index[imageArg(upstreamImageRef(c.fwd.local, img))] = refInfo{whereUpstream, img}
272					c.index[imageArg(nexusImageRef(*c.p, dockerProxyRepository, img))] = refInfo{whereProxy, img}
273				}
274			}
275		}
276		info, ok := c.index[imageArg(ref)]
277		return info, ok
278	}
279	
280	// whereOf is the registry a copy touches: the docker side of it.
281	func (c *seedCopier) whereOf(refs ...ImageRef) (string, string) {
282		for _, r := range refs {
283			if r.Transport != "docker" {
284				continue
285			}
286			if info, ok := c.lookup(r); ok {
287				return info.where, nameTag(info.img)
288			}
289			return "unknown", r.Location
290		}
291		return "none", ""
292	}
293	
294	// authorize checks the credentials offered to a registry.
295	func (c *seedCopier) authorize(where string, creds *Credentials) error {
296		var want *Credentials
297		switch where {
298		case whereHosted:
299			want = &c.admin
300		case whereProxy:
301			want = &c.pull
302		}
303		if !sameCreds(creds, want) {
304			c.t.Errorf("the %s registry was offered the wrong credentials", where)
305			return refusedImage()
306		}
307		return nil
308	}
