310	// reach fails the way a closed port-forward does.
311	func (c *seedCopier) reach(where string) error {
312		if where == whereUpstream && !c.fwd.active {
313			c.t.Errorf("the upstream was reached while the port-forward is not open")
314			return &BenchError{Kind: RegistryUnreachable, Cause: "connection refused", Check: "start the port-forward"}
315		}
316		return nil
317	}
318	
319	// read returns the manifest digest of ref the way a registry (or a layout) would.
320	func (c *seedCopier) read(ref ImageRef, creds *Credentials) (string, error) {
321		if ref.Transport == "oci" {
322			return c.readLayout(ref)
323		}
324		info, ok := c.lookup(ref)
325		if !ok || ref.Transport != "docker" {
326			c.t.Errorf("read of %s: not a reference of the data set", imageArg(ref))
327			return "", c.absent()
328		}
329		if err := c.reach(info.where); err != nil {
330			return "", err
331		}
332		if err := c.authorize(info.where, creds); err != nil {
333			return "", err
334		}
335		nt := nameTag(info.img)
336		switch info.where {
337		case whereUpstream:
338			if d, ok := c.upstream[nt]; ok {
339				return d, nil
340			}
341		case whereHosted:
342			if d, ok := c.hosted[nt]; ok {
343				return d, nil
344			}
345		case whereProxy:
346			if !info.img.PullThrough {
347				c.t.Errorf("F9: %s was read through docker-proxy, which caches it: only PullThrough images may be", nt)
348			}
349			if d, ok := c.proxyCache[nt]; ok {
350				return d, nil
351			}
352			if d, ok := c.upstream[nt]; ok {
353				c.preload(whereProxy, info.img, d)
354				return d, nil
355			}
356		}
357		return "", c.absent()
358	}
359	
360	// readLayout reads the digest of an image of the OCI layout "<dir>:<ref>".
361	func (c *seedCopier) readLayout(ref ImageRef) (string, error) {
362		i := strings.LastIndex(ref.Location, ":")
363		if i < 0 {
364			c.t.Errorf("oci reference %q has no image name", ref.Location)
365			return "", c.absent()
366		}
367		dir, name := ref.Location[:i], ref.Location[i+1:]
368		if !strings.HasPrefix(dir, c.tmp+string(os.PathSeparator)) {
369			c.t.Errorf("the layout %s is not in a temporary folder under TMPDIR (%s)", dir, c.tmp)
370		}
371		raw, err := os.ReadFile(filepath.Join(dir, "index.json"))
372		if err != nil {
373			c.t.Errorf("the layout is not readable when the copy starts: %v", err)
374			return "", c.absent()
375		}
376		var idx struct {
377			Manifests []struct {
378				Digest      string            `json:"digest"`
379				Annotations map[string]string `json:"annotations"`
380			} `json:"manifests"`
381		}
382		if err := json.Unmarshal(raw, &idx); err != nil {
383			c.t.Errorf("index.json of the layout is not JSON: %v", err)
384			return "", c.absent()
385		}
386		for _, m := range idx.Manifests {
387			if m.Annotations[annotationRefName] == name {
388				c.ociCopies++
389				return m.Digest, nil
390			}
391		}
392		c.t.Errorf("the layout holds no image called %q", name)
393		return "", c.absent()
394	}
395	
396	// Copy implements ImageCopier.
397	func (c *seedCopier) Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error {
398		c.t.Helper()
399		where, nt := c.whereOf(dst, src)
400		call := copyCall{src: src, dst: dst, opts: o, where: where}
401		c.copies = append(c.copies, call)
402		c.log.add("copy " + where + " " + nt)
403		if c.copyErr != nil {
404			if err := c.copyErr(len(c.copies), call); err != nil {
405				return err
406			}
407		}
408		if err := ctx.Err(); err != nil {
409			return &BenchError{Kind: Unclassified, Cause: "skopeo copy was interrupted", Check: "run the command again", Err: err}
410		}
411		if !o.PreserveDigests {
412			c.t.Errorf("copy of %s without PreserveDigests", nt)
413		}
414		for _, side := range []struct {
415			ref   ImageRef
416			creds *Credentials
417		}{{src, o.SrcCreds}, {dst, o.DestCreds}} {
418			if err := checkSide(side.ref, side.creds); err != nil {
419				c.t.Errorf("the real copier would refuse %s before any process: %v", imageArg(side.ref), err)
420				return err
421			}
422		}
423		digest, err := c.read(src, o.SrcCreds)
424		if err != nil {
425			return err
426		}
427		if !o.PreserveDigests {
428			sum := sha256.Sum256([]byte(digest))
429			digest = "sha256:" + hex.EncodeToString(sum[:])
430		}
431		return c.write(dst, src, digest, o.DestCreds)
432	}
433	
434	func (c *seedCopier) write(dst, src ImageRef, digest string, creds *Credentials) error {
435		switch dst.Transport {
436		case "dir":
437			if !strings.HasPrefix(dst.Location, c.tmp+string(os.PathSeparator)) {
438				c.t.Errorf("the pull-through target %s is not under TMPDIR (%s)", dst.Location, c.tmp)
439			}
440			return os.MkdirAll(dst.Location, 0o700)
441		case "docker":
442		default:
443			c.t.Errorf("destination transport %q", dst.Transport)
444			return c.absent()
445		}
446		info, ok := c.lookup(dst)
447		if !ok {
448			c.t.Errorf("write to %s: not a reference of the data set", imageArg(dst))
449			return c.absent()
450		}
451		if err := c.reach(info.where); err != nil {
452			return err
453		}
454		if info.where == whereProxy {
455			c.t.Errorf("a write through docker-proxy: it is a proxy, nothing is pushed to it")
456			return refusedImage()
457		}
458		if err := c.authorize(info.where, creds); err != nil {
459			return err
460		}
461		if src.Transport == "oci" && digest != info.img.Digest {
462			c.t.Errorf("the copy to %s %s would store %s, the data set says %s: the layout reference of another image was used",
463				info.where, nameTag(info.img), digest, info.img.Digest)
464		}
465		if info.where == whereUpstream {
466			c.upstream[nameTag(info.img)] = digest
467			return nil
468		}
469		c.preload(whereHosted, info.img, digest)
470		return nil
471	}
472	
473	// ManifestDigest implements ImageCopier.
474	func (c *seedCopier) ManifestDigest(_ context.Context, ref ImageRef, creds *Credentials) (string, error) {
475		where, nt := c.whereOf(ref)
476		call := digestCall{ref: ref, creds: creds, where: where}
477		c.digests = append(c.digests, call)
478		c.log.add("digest " + where + " " + nt)
479		if c.digestErr != nil {
480			if err := c.digestErr(call); err != nil {
481				return "", err
482			}
483		}
484		if err := checkSide(ref, creds); err != nil {
485			c.t.Errorf("the real copier would refuse %s before any process: %v", imageArg(ref), err)
486			return "", err
487		}
488		return c.read(ref, creds)
489	}
