491	// ---- the state of the registries
492	
493	// preload puts an image, with a digest, in a registry as an earlier run left it.
494	func (c *seedCopier) preload(where string, img DatasetImage, digest string) {
495		nt := nameTag(img)
496		switch where {
497		case whereUpstream:
498			c.upstream[nt] = digest
499		case whereHosted:
500			c.hosted[nt] = digest
501			c.setComponent(dockerHostedRepository, img, digest)
502		case whereProxy:
503			c.proxyCache[nt] = digest
504			c.setComponent(dockerProxyRepository, img, digest)
505		}
506	}
507	
508	// preloadAll is the registries as a complete seed leaves them.
509	func (c *seedCopier) preloadAll() {
510		for _, img := range Dataset() {
511			switch img.Location {
512			case LocationHosted:
513				c.preload(whereHosted, img, img.Digest)
514			case LocationUpstream:
515				c.preload(whereUpstream, img, img.Digest)
516				if img.PullThrough {
517					c.preload(whereProxy, img, img.Digest)
518				}
519			}
520		}
521	}
522	
523	// removeUpstream takes an image out of the upstream.
524	func (c *seedCopier) removeUpstream(img DatasetImage) { delete(c.upstream, nameTag(img)) }
525	
526	func (c *seedCopier) setComponent(repo string, img DatasetImage, digest string) {
527		comp := fakeComponent{Name: img.Name, Version: img.Tag, Digest: digest}
528		list := c.listing[repo]
529		if i := slices.IndexFunc(list, func(x fakeComponent) bool { return x.Name == comp.Name && x.Version == comp.Version }); i >= 0 {
530			list[i] = comp
531		} else {
532			list = append(list, comp)
533		}
534		c.listing[repo] = list
535		c.publish(repo)
536	}
537	
538	// addExtra lists a component outside the data set.
539	func (c *seedCopier) addExtra(repo string, comp fakeComponent) {
540		c.listing[repo] = append(c.listing[repo], comp)
541		c.publish(repo)
542	}
543	
544	func (c *seedCopier) publish(repo string) {
545		if c.hidden[repo] {
546			return
547		}
548		list := slices.Clone(c.listing[repo])
549		if c.blind[repo] {
550			for i := range list {
551				list[i].Digest = ""
552			}
553		}
554		c.nexus.SetComponents(repo, list...)
555	}
556	
557	// blindListing makes a repository list its components without a digest.
558	func (c *seedCopier) blindListing(repo string) {
559		c.blind[repo] = true
560		c.publish(repo)
561	}
562	
563	// setListedDigest changes the digest a repository lists for img, and nothing else.
564	func (c *seedCopier) setListedDigest(repo string, img DatasetImage, digest string) {
565		for i, comp := range c.listing[repo] {
566			if comp.Name == img.Name && comp.Version == img.Tag {
567				c.listing[repo][i].Digest = digest
568			}
569		}
570		c.publish(repo)
571	}
572	
573	// hide stops the instance from listing what a repository holds, until reveal.
574	func (c *seedCopier) hide(repo string) { c.hidden[repo] = true }
575	
576	func (c *seedCopier) reveal(repo string) {
577		c.hidden[repo] = false
578		c.publish(repo)
579	}
580	
581	// SetComponents replaces the listing of an existing repository.
582	func (f *fakeNexus) SetComponents(repo string, comps ...fakeComponent) {
583		f.mu.Lock()
584		defer f.mu.Unlock()
585		if !f.repoExists(repo) {
586			f.t.Fatalf("fake Nexus: no repository %q to set the components of", repo)
587		}
588		f.components[repo] = slices.Clone(comps)
589	}
