613	// newSeedEnv is a provisioned bench with an empty upstream behind the round the
614	// cluster plays. The temporary folder is private to the test: TMPDIR points at it.
615	func newSeedEnv(t *testing.T, round upstreamRound, mutate ...func(*Params)) *seedEnv {
616		t.Helper()
617		tmp := t.TempDir()
618		t.Setenv("TMPDIR", tmp)
619		b := provisioned(t)
620		p := upstreamParams()
621		for _, m := range mutate {
622			m(&p)
623		}
