716	// openedForwards counts the forwards that succeeded.
717	func (e *seedEnv) openedForwards() int {
718		n := 0
719		for _, ev := range e.log.snapshot() {
720			if ev == "forward" {
721				n++
722			}
723		}
724		if e.fwd.err != nil || n > len(e.fwd.calls) {
725			return 0
726		}
727		return n
728	}
