280	// whereOf is the registry a copy touches: the docker side of it.
281	func (c *seedCopier) whereOf(refs ...ImageRef) (string, string) {
282		for _, r := range refs {
283			if r.Transport != "docker" {
284				continue
285			}
286			if info, ok := c.lookup(r); ok {
287				return info.where, nameTag(info.img)
288			}
289			return "unknown", r.Location
290		}
291		return "none", ""
292	}
