360	// readLayout reads the digest of an image of the OCI layout "<dir>:<ref>".
361	func (c *seedCopier) readLayout(ref ImageRef) (string, error) {
362		i := strings.LastIndex(ref.Location, ":")
363		if i < 0 {
364			c.t.Errorf("oci reference %q has no image name", ref.Location)
365			return "", c.absent()
366		}
367		dir, name := ref.Location[:i], ref.Location[i+1:]
368		if !strings.HasPrefix(dir, c.tmp+string(os.PathSeparator)) {
369			c.t.Errorf("the layout %s is not in a temporary folder under TMPDIR (%s)", dir, c.tmp)
370		}
371		raw, err := os.ReadFile(filepath.Join(dir, "index.json"))
372		if err != nil {
373			c.t.Errorf("the layout is not readable when the copy starts: %v", err)
374			return "", c.absent()
375		}
376		var idx struct {
377			Manifests []struct {
378				Digest      string            `json:"digest"`
379				Annotations map[string]string `json:"annotations"`
380			} `json:"manifests"`
381		}
382		if err := json.Unmarshal(raw, &idx); err != nil {
383			c.t.Errorf("index.json of the layout is not JSON: %v", err)
384			return "", c.absent()
385		}
386		for _, m := range idx.Manifests {
387			if m.Annotations[annotationRefName] == name {
388				c.ociCopies++
389				return m.Digest, nil
390			}
391		}
392		c.t.Errorf("the layout holds no image called %q", name)
393		return "", c.absent()
394	}
