673	// checkInvariants are the rules that hold after every call, success or failure.
674	func (e *seedEnv) checkInvariants(err error) {
675		e.t.Helper()
676		// Seed reads Nexus; it never writes to it, and always as the admin account.
677		for _, r := range e.b.nexus.Requests()[e.baseline:] {
678			if r.Method != http.MethodGet {
679				e.t.Errorf("Seed sent %s %s to Nexus: it only reads", r.Method, r.Path)
680			}
681			if r.User != adminUserID {
682				e.t.Errorf("Seed sent %s %s as %q, want the admin account", r.Method, r.Path, r.User)
683			}
684		}
685		// Seed reads the cluster and writes nothing (NX-02a: it never restores the upstream).
686		if len(e.kube.writes) != 0 {
687			e.t.Errorf("Seed wrote to the cluster: %q", e.kube.writes)
688		}
689		e.kube.requireNoPreflight()
690		// One port-forward per run, always stopped.
691		if len(e.fwd.calls) > e.runs {
692			e.t.Errorf("%d port-forwards for %d runs", len(e.fwd.calls), e.runs)
693		}
694		for _, call := range e.fwd.calls {
695			if want := (forwardCall{e.p.Namespace, "bench-upstream", 5000}); call != want {
696				e.t.Errorf("port-forward to %+v, want %+v", call, want)
697			}
698		}
699		if e.fwd.active {
700			e.t.Error("the port-forward is still open when Seed returns")
701		}
702		if opened := e.openedForwards(); e.fwd.stops < opened {
703			e.t.Errorf("%d forwards opened, stop called %d times", opened, e.fwd.stops)
704		}
705		// Temporary folders.
706		if left, rerr := os.ReadDir(e.tmp); rerr != nil || len(left) != 0 {
707			names := make([]string, 0, len(left))
708			for _, f := range left {
709				names = append(names, f.Name())
710			}
711			e.t.Errorf("temporary files left under TMPDIR: %v (%v)", names, rerr)
712		}
713		e.requireQuiet(err)
714	}
