730	// requireQuiet fails when a password is in what Seed said, in its error, or in
731	// anything a process would be given on its command line.
732	func (e *seedEnv) requireQuiet(err error) {
733		e.t.Helper()
734		texts := map[string]string{"output": e.out.String(), "kubectl": strings.Join(e.kube.lines, "\n")}
735		if err != nil {
736			texts["error"] = err.Error()
737		}
738		var argv []string
739		for _, c := range e.cp.copies {
740			argv = append(argv, imageArg(c.src), imageArg(c.dst))
741		}
742		for _, c := range e.cp.digests {
743			argv = append(argv, imageArg(c.ref))
744		}
745		for _, f := range e.fwd.calls {
746			argv = append(argv, f.namespace, f.service, fmt.Sprint(f.port))
747		}
748		texts["argv"] = strings.Join(argv, "\n")
749		for label, text := range texts {
750			for _, secret := range e.secrets() {
751				if secret != "" && strings.Contains(text, secret) {
752					e.t.Errorf("the %s contains a password (%d characters): %q", label, len(secret), text)
753				}
754			}
755		}
756	}
