	b.nexus.AddComponents(dockerHostedRepository, fakeComponent{Name: "api", Version: "1.0", Digest: digest})
	b.nexus.AddComponents(dockerProxyRepository, fakeComponent{Name: "mirror/cached", Version: "1.0", Digest: digest})
}

// calls is "METHOD path" of every request, in order.
func calls(reqs []fakeReq) []string {
	out := make([]string, 0, len(reqs))
	for _, r := range reqs {
		out = append(out, r.Method+" "+r.Path)
	}
	return out
}

const invalidateSuffix = "/invalidate-cache"

func deletePath(name string) string { return pathRepositories + "/" + name }

func invalidatePath(name string) string { return pathRepositories + "/" + name + invalidateSuffix }

// proxyConfigOf is what repositorySpecs says docker-proxy is, decoded the way the
// instance decodes a body.
func proxyConfigOf(t *testing.T, p Params) map[string]any {
	t.Helper()
	for _, spec := range repositorySpecs(p) {
		if spec.name == dockerProxyRepository {
			if spec.kind != "proxy" {
				t.Fatalf("the spec of %s has kind %q, want proxy", spec.name, spec.kind)
			}
			return deepCopy(spec.config)
		}
	}
	t.Fatalf("repositorySpecs has no %s", dockerProxyRepository)
	return nil
}

// requireBenchError checks err is a complete *BenchError: a cause and what to
// check. It is not requireCleanError, which bans the word "password": the refusal of
// an account says so in the messages that already ship (asBenchError), and the
// secrets themselves are checked by bench.requireQuiet.
func requireBenchError(t *testing.T, err error) *BenchError {
	t.Helper()
	var be *BenchError
	if !errors.As(err, &be) {
		t.Fatalf("error %T is not a *BenchError: %v", err, err)
	}
	if be.Cause == "" || be.Check == "" {
		t.Errorf("the BenchError is incomplete: cause %q, check %q", be.Cause, be.Check)
	}
	return be
}

func requireAPIStatus(t *testing.T, err error, status int) *APIError {
	t.Helper()
	var api *APIError
	if !errors.As(err, &api) {
		t.Fatalf("error %T %v, want an *APIError", err, err)
	}

}

// AutoBlockProxy puts docker-proxy in the state Nexus gives a proxy whose upstream
// failed: auto-blocked. Only a successful PUT of the repository lifts it (H-UNBLOCK,
// to settle at step 0 of NX-02b: whether the PUT is enough, or the cache also has to be
// invalidated). ProxyBlocked reads it back.
func (f *fakeNexus) AutoBlockProxy() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.proxyBlocked = true
}

// ProxyBlocked reports whether docker-proxy is still auto-blocked.
func (f *fakeNexus) ProxyBlocked() bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.proxyBlocked
}

// MarkNegativeCached makes the negative cache of a repository hold an entry, as a
// proxy does once its upstream answered "not found" or did not answer. Only
// invalidate-cache empties it.
func (f *fakeNexus) MarkNegativeCached(name string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.negativeCached[name] = true
}

// NegativeCached reports whether the negative cache of a repository still holds an entry.
func (f *fakeNexus) NegativeCached(name string) bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.negativeCached[name]
}

// KeepComponentsAfterDelete makes every repository deleted from now on keep listing
// its old components for n more listings (one per request of the components
// endpoint, a page counts), as a storage that empties late would. The repository
// itself is gone at once; a repository recreated under the same name shows the old
// components until the n listings have passed. This is H-REPODEL being false for n
// reads.
func (f *fakeNexus) KeepComponentsAfterDelete(n int) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.keepAfterDelete = n
}

// ComponentCount is how many components the instance holds for a repository name,
// whether or not the repository exists.
func (f *fakeNexus) ComponentCount(repo string) int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return len(f.components[repo])
}

// DropConnections makes the instance close every connection without an answer.
func (f *fakeNexus) DropConnections() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.dropAll = true
}
