		} else {
			delete(f.components, name)
		}
		f.reply(w, r, http.StatusNoContent, nil)
	case len(parts) == 2 && parts[1] == "invalidate-cache" && r.Method == http.MethodPost:
		switch {
		case !found:
			f.reply(w, r, http.StatusNotFound, nil)
		case kind == "hosted":
