		}
	case len(parts) == 1 || (len(parts) == 2 && parts[1] == "invalidate-cache"):
		f.reply(w, r, http.StatusMethodNotAllowed, nil)
	default:
		f.reply(w, r, http.StatusNotFound, nil)
	}
}

