			injected := &BenchError{Kind: RegistryRefused, Cause: "a registry refused the skopeo copy", Check: "check the credentials"}
			e.cp.copyErr = func(n int, _ copyCall) error {
				if n == tt.at {
					return injected
				}
				return nil
			}

			_, err := e.run()
			if err == nil {
				t.Fatal("Seed succeeded")
			}
