package nexusbench

import (
	"context"
	"fmt"
	"io"
	"strings"
)

func RestoreUpstream(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) error {
	if out == nil {
		out = io.Discard
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if !p.UpstreamIsBench() {
		return customUpstreamError(p)
	}
	admin, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
	if err != nil {
		return err
	}
	defer c.closeIdle()
	if err := EnsureUpstream(ctx, d.Runner, d.Clock, p, out); err != nil {
		return err
	}
	if err := UnblockProxy(ctx, d.Store, baseURL, p, out); err != nil {
		return err
	}
	s := &seeder{ctx: ctx, d: d, p: p, out: out, c: c, baseURL: baseURL, admin: admin, pull: pull, images: Dataset()}
	if err := s.verifyUpstream(); err != nil {
		return err
	}
	return s.verifyProxy()
}

func (s *seeder) verifyUpstream() error {
	local, stop, err := s.d.Forwarder.Forward(s.ctx, s.p.Namespace, upstreamServiceName, upstreamServicePort)
	if err != nil {
		return s.failure(err, "the port-forward to the upstream")
	}
	if stop != nil {
		defer func() { _ = stop() }()
	}
	if !strings.HasPrefix(local, seedLoopbackHost+":") || !loopbackRegistry(local) {
		return &BenchError{Kind: SeedFailed, Cause: "the port-forward to the upstream is not on 127.0.0.1", Check: "check the kubectl on PATH, mise"}
	}
	for _, img := range s.images {
		if img.Location != LocationUpstream {
			continue
		}
		name := img.Name + ":" + img.Tag
		have, err := s.d.Copier.ManifestDigest(s.ctx, upstreamImageRef(local, img), nil)
		if errorsIs(err, errImageAbsent) {
			return &BenchError{Kind: SeedFailed, Cause: "the upstream lost " + name, Check: resetCheck}
		}
		if err != nil {
			return s.failure(err, "reading "+name+" in the upstream")
		}
		if have != img.Digest {
			return &BenchError{Kind: SeedFailed, Cause: "the upstream holds another content for " + name, Check: resetCheck}
		}
	}
	return nil
}

func (s *seeder) verifyProxy() error {
	for _, img := range s.images {
		if !img.PullThrough {
			continue
		}
		name := img.Name + ":" + img.Tag
		have, err := s.d.Copier.ManifestDigest(s.ctx, nexusImageRef(s.p, dockerProxyRepository, img), &s.pull)
		if err != nil {
			return s.failure(err, "reading "+name+" through "+dockerProxyRepository)
		}
		if have != img.Digest {
			return &BenchError{Kind: SeedFailed, Cause: dockerProxyRepository + " serves another content for " + name, Check: resetCheck}
		}
	}
	return nil
}

func recycleUpstreamStorage(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
	if out == nil {
		out = io.Discard
	}
	if err := CutUpstream(ctx, r, clk, p, out); err != nil {
		return err
	}
	d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
	ns := p.Namespace
	get := []string{"get", "pvc", upstreamClaim, "-n", ns, "-o", "json"}
	var claim struct {
		Metadata struct {
			Labels map[string]string `json:"labels"`
		} `json:"metadata"`
	}
	found, err := d.fetch(ctx, "read the claim "+upstreamClaim, get, &claim, true)
	if err != nil {
		return err
	}
	if found {
		if claim.Metadata.Labels[managedByLabel] != managedByValue {
			return &BenchError{Kind: Unclassified, Cause: fmt.Sprintf("the claim %s does not carry the label %s=%s, so the bench did not create it", upstreamClaim, managedByLabel, managedByValue),
				Check: d.pf.command("get", "pvc", upstreamClaim, "-n", ns, "--show-labels")}
		}
		args := []string{"delete", "pvc", upstreamClaim, "-n", ns, "--wait=false", applyTimeout}
		_, errOut, err := r.Run(ctx, nil, args...)
		if err != nil {
			if cerr := ctx.Err(); cerr != nil {
				return cerr
			}
			return d.pf.failure("delete the claim "+upstreamClaim, args, string(errOut), err)
		}
		deadline := clk.Now().Add(p.DeleteTimeout)
		for {
			found, err := d.fetch(ctx, "read the claim "+upstreamClaim, get, &claim, true)
			if err != nil {
				return err
			}
			if !found {
				break
